compile.workshop:
variables {
    global:
        0: g
        1: h
}

rule ("folds see the authored literal") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, Min(False, 3));
        Set Global Variable(g, Min(3, True));
        Set Global Variable(g, Max(False, 3));
        Set Global Variable(g, Max(3, True));
        Set Global Variable(g, Array Slice(Array(1, 2), False, 3));
        Set Global Variable(g, Array Slice(Array(1, 2), 3, True));
        Set Global Variable(g, -1);
        Set Global Variable(g, String Replace(Custom String("s"), Empty Array, Custom String("s")));
        Set Global Variable(g, String Replace(Custom String("s"), Custom String("s"), Empty Array));
        Set Global Variable(g, String Replace(Custom String("s"), Custom String("s"), Update Every Frame(Null)));
        Create HUD Text(All Players(All Teams), Empty Array, 3, 3, Left, 3, Color(Yellow), Color(Yellow), Color(Yellow), Visible To Sort Order String and Color, Default Visibility);
    }
}

